<?php require_once __DIR__.'/../../includes/functions.php'; admin_required(); $edit=null; try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);if(!$name)throw new RuntimeException('Name is required.');$data=[$_POST['category_id']?:null,$name,slug($name),trim((string)$_POST['short_description']),trim((string)$_POST['description']),trim((string)$_POST['location']),$_POST['latitude']?:null,$_POST['longitude']?:null,trim((string)$_POST['maps_url']),$_POST['status']??'active'];if($id){$stmt=db()->prepare('UPDATE destinations SET category_id=?,name=?,slug=?,short_description=?,description=?,location=?,latitude=?,longitude=?,maps_url=?,status=? WHERE id=?');$stmt->execute([...$data,$id]);log_activity('update_destination',$name);}else{$stmt=db()->prepare('INSERT INTO destinations(category_id,name,slug,short_description,description,location,latitude,longitude,maps_url,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$stmt->execute($data);log_activity('add_destination',$name);}flash('success','Destination saved.');redirect('index.php');}if(isset($_GET['delete'])){db()->prepare('DELETE FROM destinations WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Destination deleted.');redirect('index.php');}}catch(Throwable $e){flash('danger',$e->getMessage());} $edit=isset($_GET['edit'])?(function(){$s=db()->prepare('SELECT * FROM destinations WHERE id=?');$s->execute([(int)$_GET['edit']]);return $s->fetch();})():null;$cats=db()->query("SELECT id,name FROM categories WHERE status='active' ORDER BY name")->fetchAll();$rows=db()->query('SELECT d.*,c.name category_name FROM destinations d LEFT JOIN categories c ON c.id=d.category_id ORDER BY d.created_at DESC')->fetchAll();$title='Destinations';include __DIR__.'/../../includes/header.php';?>
<main class="container py-5"><div class="d-flex justify-content-between"><h1 class="display-serif">Destinations</h1><a class="btn btn-success" href="?new=1">Add destination</a></div><?php if($edit||isset($_GET['new'])):?><div class="card p-4 my-4"><h2 class="h5"><?= $edit?'Edit':'New'?> destination</h2><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Name<input class="form-control" name="name" required value="<?=e($edit['name']??'')?>"></label></div><div class="col-md-3"><label class="form-label">Category<select class="form-select" name="category_id"><option value="">None</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label></div><div class="col-md-3"><label class="form-label">Status<select class="form-select" name="status"><option>active</option><option <?=($edit['status']??'')==='inactive'?'selected':''?>>inactive</option></select></label></div><div class="col-12"><label class="form-label">Short description<input class="form-control" name="short_description" value="<?=e($edit['short_description']??'')?>"></label></div><div class="col-12"><label class="form-label">Full description<textarea class="form-control" name="description"><?=e($edit['description']??'')?></textarea></label></div><div class="col-md-4"><label class="form-label">Location<input class="form-control" name="location" value="<?=e($edit['location']??'')?>"></label></div><div class="col-md-2"><label class="form-label">Latitude<input class="form-control" name="latitude" value="<?=e($edit['latitude']??'')?>"></label></div><div class="col-md-2"><label class="form-label">Longitude<input class="form-control" name="longitude" value="<?=e($edit['longitude']??'')?>"></label></div><div class="col-md-4"><label class="form-label">Maps URL<input class="form-control" type="url" name="maps_url" value="<?=e($edit['maps_url']??'')?>"></label></div></div><button class="btn btn-success mt-3">Save</button> <a class="btn btn-light mt-3" href="index.php">Cancel</a></form></div><?php endif;?><div class="card p-3 mt-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Name</th><th>Category</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['category_name']??'—')?></td><td><span class="badge text-bg-<?=$r['status']==='active'?'success':'secondary'?>"><?=e($r['status'])?></span></td><td class="text-end"><a href="?edit=<?=$r['id']?>" class="btn btn-sm btn-outline-success">Edit</a> <a data-confirm="Delete this destination and its attractions?" href="?delete=<?=$r['id']?>" class="btn btn-sm btn-outline-danger">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></main><?php include __DIR__.'/../../includes/footer.php';?>
